def t(key: str, language: str = 'ru', **kwargs):
    row = ROWS.get(key)
    if row is None:
        raise KeyError('Missing interface translation: ' + key)
    idx = {'ru': 0, 'de': 1, 'en': 2}.get(language, 0)
    return row[idx].format(**kwargs)


def method_label(method: str, language: str):
    return t({'Laser':'laser','Plasma':'plasma','Wasserstrahl':'waterjet',
              'Autogen':'autogen','CNC Konturfräsen':'cnc'}[method],language)


def material_label(material: str, language: str):
    return t({'Kupfer':'copper','Messing':'brass','Kunststoff':'plastic'}[material],language) if material in ('Kupfer','Messing','Kunststoff') else material


# CAD-core warnings are intentionally German in the saved JSON diagnostics.
# Translate common user-facing warnings while keeping original strings in ZIP.
def engine_warning(message: str, language: str) -> str:
    if language == 'de':
        return message
    if 'Verschachtelte Teile in Ausschnitten/Taschen' in message:
        return ('Вложенные детали: сначала внутренние детали, затем окружающие контуры. Проверить перемычки, фиксацию и CAM.'
            if language == 'ru' else
            'Nested parts: inner pieces precede surrounding contours. Verify tabs, workholding and CAM.')
    if 'Teileabstand kleiner als Schnittbreite' in message:
        return ('Зазор между деталями меньше ширины реза / диаметра фрезы: возможны пересечения траекторий.'
            if language == 'ru' else
            'Part gap is smaller than the kerf / cutter diameter: toolpaths may overlap.')
    if 'sicherer geradliniger Eintritt' in message:
        part = message.split(':',1)[0]
        return (f'{part}: прямолинейный заход не подтверждён; требуется проверка в CAM.'
            if language == 'ru' else
            f'{part}: safe straight lead-in unverified; CAM planning required.')
    if 'kleiner als Schnittbreite; Kontur nicht bearbeitbar' in message:
        part = message.split(':',1)[0]
        return (f'{part}: контур слишком узкий для выбранного инструмента / пропила.'
            if language == 'ru' else
            f'{part}: contour too small for selected cutter / kerf.')
    if message.startswith('CNC: Zustellung'):
        return ('CNC: проверить подачу по Z, нагрузки инструмента, фиксацию, перемычки и заходы в CAM.'
            if language == 'ru' else
            'CNC: validate depth passes, cutter loads, clamping, tabs and lead-ins in CAM.')
    if 'Konturen geometrisch nicht fräs-/schneidbar' in message:
        return ('Часть контуров не обработана: стоимость и время неполные.'
            if language == 'ru' else
            'Some contours cannot be machined: time and cost are incomplete.')
    return message


def localized_table(table: list[dict], language: str) -> list[dict]:
    mapping = {'Teil':'table_part','Blech':'table_sheet','Drehung_grad':'table_angle',
         'Nettoflaeche_mm2':'table_netarea','Kontur_mm':'table_contour',
         'Lochzahl':'table_holecount','Verschachtelt_in':'table_nested_in',
         'Tasche_Typ':'table_pocket_type','Nr':'table_order','Eintritt_ok':'table_entry',
         'X_Start_mm':'table_start_x','Y_Start_mm':'table_start_y',
         'X_Anfahrt_mm':'table_approach_x','Y_Anfahrt_mm':'table_approach_y',
         'Schnittweg_mm':'table_cut_mm','Anfahrt_mm':'table_lead_mm',
         'Eilweg_mm':'table_rapid_mm'}
    return [{(t(mapping[k], language) if k in mapping else k):v for k,v in row.items()}
            for row in table]
